<?php

namespace App\Console\Commands;

use App\Models\AttendanceMark;
use App\Models\AttendanceRecord;
use App\Models\Student;
use Carbon\Carbon;
use Illuminate\Console\Command;
use Illuminate\Database\QueryException;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Log;

class SendAbsenceAlerts extends Command
{
    protected $signature = 'alerts:absence {--date= : YYYY-MM-DD (default today)}';
        protected $description = 'Send WhatsApp absence alerts to guardians';

            public function handle(): int
                {
                        if (! config('services.whatsapp.auto_absence')) {
                                    $this->warn('Auto absence alerts are OFF.');
                                                return self::SUCCESS;
                                                        }
                                                                $given = $this->option('date');
                                                                        $day = $given ? Carbon::parse($given) : Carbon::now('Asia/Karachi');
                                                                                if (! $given && $day->isWeekend()) {
                                                                                            $this->info('Weekend, skipping.');
                                                                                                        return self::SUCCESS;
                                                                                                                }
                                                                                                                        $date = $day->toDateString();
                                                                                                                                $dry = (bool) config('services.whatsapp.dry_run');
                                                                                                                                        $token = config('services.whatsapp.token');
                                                                                                                                                $phoneId = config('services.whatsapp.phone_id');
                                                                                                                                                        if (! $dry && (! $token || ! $phoneId)) {
                                                                                                                                                                    $this->error('WhatsApp token or phone id missing.');
                                                                                                                                                                                return self::FAILURE;
                                                                                                                                                                                        }
                                                                                                                                                                                                $this->info(($dry ? 'DRY-RUN' : 'LIVE') . " absence alerts for {$date}");
                                                                                                                                                                                                        $found = 0; $sent = 0; $skipped = 0; $noPhone = 0; $failed = 0;

                                                                                                                                                                                                                foreach (AttendanceRecord::whereDate('date', $date)->get() as $record) {
                                                                                                                                                                                                                            $present = AttendanceMark::where('attendance_record_id', $record->id)
                                                                                                                                                                                                                                            ->whereIn('status', ['P', 'L'])->pluck('student_id');
                                                                                                                                                                                                                                                        $students = Student::where('class', $record->class_name)
                                                                                                                                                                                                                                                                        ->where('passed_out', false)->whereNotIn('id', $present)
                                                                                                                                                                                                                                                                                        ->orderBy('name')->get();
                                                                                                                                                                                                                                                                                                    foreach ($students as $s) {
                                                                                                                                                                                                                                                                                                                    $found++;
                                                                                                                                                                                                                                                                                                                                    $to = $this->phone($s->guardian_phone);
                                                                                                                                                                                                                                                                                                                                                    if (! $to) { $noPhone++; continue; }
                                                                                                                                                                                                                                                                                                                                                                    $cls = trim(preg_replace('/^class\s+/i', '', (string) $record->class_name));
                                                                                                                                                                                                                                                                                                                                                                                    $params = [$s->name, $cls, $day->format('j F Y')];
                                                                                                                                                                                                                                                                                                                                                                                                    if ($dry) {
                                                                                                                                                                                                                                                                                                                                                                                                                        $this->line("would send to {$to}: " . implode(' | ', $params));
                                                                                                                                                                                                                                                                                                                                                                                                                                            Log::info('WA dry-run absence', ['to' => $to, 'params' => $params]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                $sent++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        DB::table('whatsapp_notify_logs')->insert([
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'student_id' => $s->id, 'date' => $date, 'kind' => 'absence',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'created_at' => now(), 'updated_at' => now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (QueryException $e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if ((string) $e->getCode() === '23000') { $skipped++; } else { $failed++; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $res = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $res = Http::withToken($token)->timeout(20)->post(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "https://graph.facebook.com/v22.0/{$phoneId}/messages",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'messaging_product' => 'whatsapp',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'to' => $to,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'type' => 'template',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'template' => [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'name' => 'student_absence_alert',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'language' => ['code' => 'en_US'],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'components' => [[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'type' => 'body',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'parameters' => array_map(fn ($t) => ['type' => 'text', 'text' => (string) $t], $params),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ]],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $ok = $res->successful();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (\Throwable $e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $ok = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if ($ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $sent++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $failed++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            DB::table('whatsapp_notify_logs')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ->where('student_id', $s->id)->where('date', $date)->where('kind', 'absence')->delete();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Log::warning('WA absence failed', ['student' => $s->id, 'body' => $res ? $res->body() : 'exception']);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $this->info("absent={$found} " . ($dry ? 'would_send' : 'sent') . "={$sent} duplicate={$skipped} no_phone={$noPhone} failed={$failed}");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return self::SUCCESS;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private function phone(?string $raw): ?string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $d = preg_replace('/\D+/', '', (string) $raw);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if ($d === '') { return null; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (str_starts_with($d, '0')) { return '92' . substr($d, 1); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (str_starts_with($d, '92')) { return $d; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (strlen($d) === 10) { return '92' . $d; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return $d;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }